import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Plugin API: ABI and runtime support","description":"Match the Pumpkin server to the plugin ABI and check engine support","frontmatter":{"navigation":{"category":"Plugin API"},"title":"Plugin API: ABI and runtime support","description":"Match the Pumpkin server to the plugin ABI and check engine support","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/plugin-api/abi-and-runtime.md"},"headers":[],"relativePath":"docs/plugin-api/abi-and-runtime.md","filePath":"docs/plugin-api/abi-and-runtime.md","lastUpdated":1792252051000}`),a={name:`docs/plugin-api/abi-and-runtime.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="abi-and-runtime-compatibility" tabindex="-1">ABI and runtime compatibility <a class="header-anchor" href="#abi-and-runtime-compatibility" aria-label="Permalink to “ABI and runtime compatibility”">​</a></h1><p>When a plugin will not load or an API call is unavailable, check two things: whether the plugin&#39;s WIT ABI matches the Pumpkin server, and whether the chosen engine implements that operation. The package version and generated TypeScript declarations cannot answer both questions on their own.</p><h2 id="match-the-wit-abi-to-the-pumpkin-server" tabindex="-1">Match the WIT ABI to the Pumpkin server <a class="header-anchor" href="#match-the-wit-abi-to-the-pumpkin-server" aria-label="Permalink to “Match the WIT ABI to the Pumpkin server”">​</a></h2><p>The npm version identifies the TypeScript facade release; the WIT version identifies the host ABI. They are separate pins. The current alignment is:</p><table tabindex="0"><thead><tr><th>Pin</th><th>Current value</th><th>Source of truth</th></tr></thead><tbody><tr><td>API package</td><td><code>@pumpkin-plugins/pumpkin-api</code> <code>0.1.0</code></td><td><a href="../../tools/pumpkin-api/package.json"><code>package.json</code></a></td></tr><tr><td>Pumpkin plugin ABI</td><td><code>pumpkin:plugin@0.1.0</code> from WIT subdirectory <code>v0.1</code></td><td><a href="../../tools/pumpkin-api/wit.lock.json"><code>wit.lock.json</code></a></td></tr><tr><td>Pumpkin server</td><td><code>0.2.0+26.3-26.51</code></td><td><a href="../../tools/test-harness/src/pumpkin-version.ts"><code>pumpkin-version.ts</code></a></td></tr><tr><td>Upstream WIT source</td><td>Commit <code>4d7a501943bb99f0f02a339128833f58ed37d0cc</code></td><td><a href="../../tools/pumpkin-api/wit.lock.json"><code>wit.lock.json</code></a></td></tr></tbody></table><p>The API package&#39;s <code>wit.lock.json</code> pins the upstream repository, commit, and WIT subdirectory. The build tool fetches that exact commit on first use and when the lock changes, then stores it in the consumer project&#39;s ignored <code>.cache/pumpkin-api-wit/&lt;lock-digest&gt;/</code> directory. It generates guest declarations from that fetched WIT, so your declarations describe the pinned ABI rather than an unlocked copy of the upstream branch. See <a href="/pumpkin-plugins/docs/plugin-api/setup-and-build">Setup and build</a> for the commands.</p><p>Keep the API package&#39;s WIT pin aligned with the Pumpkin release in <a href="../../tools/test-harness/src/pumpkin-version.ts"><code>tools/test-harness/src/pumpkin-version.ts</code></a>. The server must provide compatible component imports; if the pins drift, the server may be unable to resolve the imports the plugin was built against. When changing the target server, verify its WIT source first, then update the lock and server pin together.</p><h2 id="check-support-in-the-selected-engine" tabindex="-1">Check support in the selected engine <a class="header-anchor" href="#check-support-in-the-selected-engine" aria-label="Permalink to “Check support in the selected engine”">​</a></h2><p>QuickJS and Static Hermes use different runtime paths and have different limits. For QuickJS caveats, see <a href="/pumpkin-plugins/guides/building#runtime-caveats">Building</a>. Static Hermes implements only a subset of the Pumpkin API through its native JSI shim; check the <a href="./../../tools/static-hermes-runtime/README#api-and-platform-coverage">runtime coverage guide</a> before relying on an operation there.</p><p>Generated TypeScript declarations come from the WIT ABI. They do not guarantee that every declared operation is implemented by Static Hermes. The pinned server also has a separate limitation: it does not start custom WASM AI goals, even though the Static Hermes adapter can dispatch their callbacks. See the <a href="./../../tools/static-hermes-runtime/docs/">Static Hermes Runtime guide</a> for the host details and source link.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};